nextflow_process {

    name "Test Process PROKKA"
    script "../main.nf"
    process "PROKKA"

    tag "modules"
    tag "modules_nfcore"
    tag "prokka"

    test("Prokka - sarscov2 - genome.fasta") {

        when {
            process {
                """
                input[0] =  Channel.fromList([
                        tuple([ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true))
                    ])
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["gbk", "log", "sqn"])).match()}
            )
        }

    }

    test("Prokka - sarscov2 - genome.fasta.gz") {

        when {
            process {
                """
                input[0] =  Channel.fromList([
                        tuple([ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.gz', checkIfExists: true))
                    ])
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["gbk", "log", "sqn"])).match()}
            )
        }

    }

    test("Prokka - sarscov2 - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] =  Channel.fromList([
                        tuple([ id:'test', single_end:false ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.gz', checkIfExists: true))
                    ])
                input[1] = []
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }

}

